/* FitFlow service worker — generated by scripts/postbuild.mjs. Do not edit sw.js directly. */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const SCOPE = self.registration.scope; // e.g. https://user.github.io/fitflow/
const CACHE = `fitflow-${VERSION}`;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      cache.addAll(PRECACHE.map((u) => new Request(new URL(u, SCOPE).href, { cache: "reload" }))),
    ),
  );
  // No skipWaiting here: an update waits until the user taps "update", so a
  // page never runs against assets from a different version.
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) {
        if (key.startsWith("fitflow-") && key !== CACHE) await caches.delete(key);
      }
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

async function fromCache(request) {
  const cache = await caches.open(CACHE);
  return (await cache.match(request)) || (await cache.match(request, { ignoreSearch: true }));
}

async function networkFirst(request, timeoutMs) {
  const cache = await caches.open(CACHE);
  try {
    const response = await Promise.race([
      fetch(request),
      new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), timeoutMs)),
    ]);
    if (response && response.ok) cache.put(request, response.clone());
    return response;
  } catch (e) {
    const cached = await fromCache(request);
    if (cached) return cached;
    throw e;
  }
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE);
  const cached = await fromCache(request);
  const network = fetch(request)
    .then((r) => {
      if (r && r.ok) cache.put(request, r.clone());
      return r;
    })
    .catch(() => undefined);
  return cached || (await network) || new Response("Offline", { status: 503 });
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (!url.href.startsWith(SCOPE)) return; // Supabase API etc. go straight to the network
  const path = url.href.slice(SCOPE.length);

  if (req.mode === "navigate") {
    event.respondWith(
      networkFirst(req, 4000).catch(async () => {
        const page = url.pathname.endsWith("/") ? url.href : `${url.href}/`;
        return (
          (await fromCache(new Request(page))) ||
          (await fromCache(new Request(SCOPE))) ||
          new Response("<h1>Offline</h1><p>Open FitFlow once while online first.</p>", {
            headers: { "Content-Type": "text/html" },
          })
        );
      }),
    );
    return;
  }
  if (path.startsWith("_next/static/")) {
    event.respondWith(fromCache(req).then((c) => c || fetch(req)));
    return;
  }
  if (path === "config.js" || path === "manifest.webmanifest" || path === "exercise-videos.json") {
    event.respondWith(networkFirst(req, 3000));
    return;
  }
  event.respondWith(staleWhileRevalidate(req));
});

// ---------------------------------------------------------------- Web Push
self.addEventListener("push", (event) => {
  let d = {};
  try {
    d = event.data ? event.data.json() : {};
  } catch (e) {
    d = { title: "FitFlow", body: event.data ? event.data.text() : "" };
  }
  event.waitUntil(
    (async () => {
      // iOS requires every push to show a visible notification.
      await self.registration.showNotification(d.title || "FitFlow", {
        body: d.body || "",
        tag: d.tag || undefined,
        data: { url: d.url || "./", log_id: d.log_id || null },
        icon: new URL("icons/icon-192.png", SCOPE).href,
        badge: new URL("icons/badge-72.png", SCOPE).href,
        timestamp: Date.now(),
      });
      const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      for (const c of windows) c.postMessage({ type: "push-shown", log_id: d.log_id, kind: d.kind });
      // Tell the server this device really displayed it (used for honest test results).
      if (d.receipt_url && d.receipt_token) {
        try {
          const key = new URL(d.receipt_url).searchParams.get("apikey");
          await fetch(d.receipt_url, {
            method: "POST",
            headers: key ? { "Content-Type": "application/json", apikey: key } : { "Content-Type": "application/json" },
            body: JSON.stringify({ token: d.receipt_token }),
          });
        } catch (e) {
          /* offline: the notification was still shown */
        }
      }
    })(),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = new URL((event.notification.data && event.notification.data.url) || "./", SCOPE).href;
  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      for (const c of windows) {
        if (c.url.startsWith(SCOPE) && "focus" in c) {
          try {
            await c.navigate(target);
          } catch (e) {
            /* navigation not allowed: just focus */
          }
          return c.focus();
        }
      }
      return self.clients.openWindow(target);
    })(),
  );
});
